mapper.sql:
EXISTS (SELECT 1 FROM outbox_delivery d WHERE d.tenant_id=source_completion_checkpoint.tenant_id
  AND d.event_id=source_completion_checkpoint.event_id AND d.consumer_id=source_completion_checkpoint.consumer_id
  AND d.created_by=#{userId} AND d.status='DELIVERING' AND d.lease_owner=#{leaseOwner}
  AND d.lease_generation=#{generation} AND d.revision=#{leaseRevision}
  AND d.lease_until>UTC_TIMESTAMP(6))

mapper.insert:
INSERT INTO source_completion_checkpoint(project_id,upload_id,operation_id,event_id,consumer_id,input_sha256,
  scan_command,scan_receipt,write_intent,object_ref,status,schema_version,schema_manifest_sha256,
  created_by,created_at,classification,revision,updated_at)
SELECT #{projectId},#{uploadId},#{operationId},#{eventId},#{consumerId},#{inputSha256},#{scanCommand},#{scanReceipt},
  #{writeIntent},NULL,'WRITING','1.0.0',#{manifest},#{userId},#{now},#{classification},1,#{now}
FROM outbox_delivery d WHERE d.event_id=#{eventId} AND d.consumer_id=#{consumerId} AND d.created_by=#{userId}
  AND d.status='DELIVERING' AND d.lease_owner=#{leaseOwner} AND d.lease_generation=#{generation}
  AND d.revision=#{leaseRevision} AND d.lease_until>UTC_TIMESTAMP(6)

mapper.update:
UPDATE source_completion_checkpoint SET object_ref=#{objectRef},status='ORIGINAL_VERIFIED',revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id=#{consumerId} AND upload_id=#{uploadId} AND operation_id=#{operationId}
  AND created_by=#{userId} AND revision=#{revision} AND status='WRITING' AND object_ref IS NULL
  AND

UPDATE upload_item SET actual_sha256=#{artifactSha256},object_ref=#{objectRef},status='RECEIVED',revision=revision+1,updated_at=#{now}
WHERE upload_id=#{uploadId} AND project_id=#{projectId} AND created_by=#{userId} AND status='UPLOADING'
  AND revision=#{sourceRevision} AND received_size=expected_size AND actual_sha256 IS NULL AND object_ref IS NULL

UPDATE operation_record SET state='COMPLETED',http_status=202,response_ref=#{response},revision=revision+1,updated_at=#{now}
WHERE operation_id=#{operationId} AND subject_id=#{userId} AND created_by=#{userId} AND operation_name='KN-03'
  AND target_id=#{uploadId} AND state='PROCESSING' AND revision=1 AND response_ref IS NULL AND error_code IS NULL
  AND request_sha256=#{requestSha256}

UPDATE outbox_delivery SET status='DELIVERED',lease_owner=NULL,lease_until=NULL,revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id=#{consumerId} AND created_by=#{userId} AND status='DELIVERING'
  AND lease_owner=#{leaseOwner} AND lease_generation=#{generation} AND revision=#{leaseRevision}
  AND lease_until>UTC_TIMESTAMP(6) AND completion_deadline>UTC_TIMESTAMP(6)

UPDATE outbox_delivery SET completion_started_at=#{now},completion_deadline=#{deadline},completion_manifest=#{completionManifest}
WHERE event_id=#{eventId} AND consumer_id=#{consumerId} AND created_by=#{userId} AND status='DELIVERING'
  AND lease_owner=#{leaseOwner} AND lease_generation=#{generation} AND revision=#{leaseRevision} AND lease_until>#{now}
  AND completion_started_at IS NULL AND completion_deadline IS NULL AND completion_manifest IS NULL

UPDATE outbox_delivery SET status='FAILED',lease_owner=NULL,lease_until=NULL,last_error=#{reason},revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id=#{consumerId} AND created_by=#{userId}
  AND lease_owner<=>#{leaseOwner} AND lease_generation=#{generation} AND revision=#{leaseRevision}
  AND ((#{liveFailure}=TRUE AND status='DELIVERING' AND lease_until>#{now})
    OR (#{liveFailure}=FALSE AND (status='PENDING' OR status='DELIVERING' AND lease_until<=#{now})))

UPDATE object_upload_session SET state='FAILED',revision=revision+1,updated_at=#{now}
WHERE upload_id=#{uploadId} AND project_id=#{projectId} AND created_by=#{userId} AND purpose='SOURCE'
  AND state='COMPLETING' AND revision=#{sessionRevision}

UPDATE operation_record SET state='FAILED',http_status=202,response_ref=#{response},error_code='PROCESSING_FAILED',revision=revision+1,updated_at=#{now}
WHERE operation_id=#{operationId} AND subject_id=#{userId} AND created_by=#{userId} AND operation_name='KN-03'
  AND target_id=#{uploadId} AND state='PROCESSING' AND revision=1 AND response_ref IS NULL AND error_code IS NULL
  AND request_sha256=#{requestSha256}
